def _(rid, params: dict, _root=_relay_root) -> dict:
    """Replace this gateway's view of agents on OTHER connections → ``{count}`` accepted rows
    (``agents`` rows ``{profile, handle, connection_id, ...}``; invalid rows are dropped).
    A roster that changes is logged with its rows: a peer connection listed with this machine's
    own profiles, or two publishers alternating, shows up as a flapping line (the pushing window
    is in the Desktop's desktop.log ``[bot-relay win=…]`` lines at the same time)."""
    try:
        from tools.bot_relay import read_remote_roster, write_remote_roster

        def trace() -> str:
            rows = read_remote_roster(_root())
            return f"n={len(rows)} [" + " ".join(
                f"{r.get('connection_id')}/{r.get('profile')}={r.get('title')!r}" for r in rows) + "]"

        before = trace()
        count = write_remote_roster(_root(), params.get("agents"))
        after = trace()
        if after != before:
            logging.getLogger(__name__).info("bot_relay roster changed: %s -> %s", before, after)
        return _ok(rid, {"count": count})
    except Exception as e:
        return _err(rid, 5090, str(e))

def _(rid, params: dict, _root=_relay_root) -> dict:
    """Claim every pending cross-connection envelope queued here → ``{envelopes}``; claimed
    envelopes move to ``claimed/`` atomically so concurrent drains can't double-deliver."""
    try:
        from tools.bot_relay import claim_pending_envelopes
        return _ok(rid, {"envelopes": claim_pending_envelopes(_root())})
    except Exception as e:
        return _err(rid, 5091, str(e))

def _(rid, params: dict, _root=_relay_root) -> dict:
    """Write a relayed ``reply`` and/or ``error`` (+ optional typed ``reason``, see
    ``tools.bot_failure_reasons``) for envelope ``id`` so the sender-side waiter picks it up."""
    envelope_id = str(params.get("id") or "").strip()
    if not envelope_id:
        return _err(rid, 4093, "id required")
    try:
        from tools.bot_relay import write_reply
        write_reply(_root(), envelope_id, reply=str(params.get("reply") or ""),
                    error=str(params.get("error") or ""), reason=str(params.get("reason") or ""))
        return _ok(rid, {"ok": True})
    except ValueError as e:
        return _err(rid, 4094, str(e))
    except Exception as e:
        return _err(rid, 5095, str(e))

def _(rid, params: dict) -> dict:
    word = params.get("word", "")
    if not word:
        return _ok(rid, {"items": []})
    session = _sessions.get(params.get("session_id", ""))
    local = _effective_terminal_backend() == "local"
    # A non-local backend's cwd lives inside the target; the host cannot validate it, so take the composer's
    # session cwd (Desktop sends it) or the session's terminal cwd as-is (".": the backend's own cwd). The TUI
    # echoes session.info's cwd back; for a sandbox session nobody gave a workspace that is the host launch dir.
    client_cwd = params.get("cwd")
    if session and client_cwd == session.get("cwd") and _is_remote_launch_cwd(session):
        client_cwd = None
    root = _completion_cwd(params) if local else (client_cwd or _terminal_task_cwd(session) or ".")
    session_key = session.get("session_key") if session else None
    return _ok(rid, {"items": _path_completion_items(word, root, session_key, local)})

def _(rid, params: dict) -> dict:
    skew = _model_skew_err(rid)
    if skew is not None:
        return skew
    from hermes_cli.inventory import build_model_options_payload
    # A spawned agent owns the live provider/model/base_url; empty attributes must
    # NOT clobber disk config (with_overrides is truthy-only).
    return _ok(rid, build_model_options_payload(
        _model_picker_context(_session_agent(params)), explicit_only=bool(params.get("explicit_only")),
        include_unconfigured=bool(params.get("include_unconfigured")), refresh=bool(params.get("refresh"))))

def _(rid, params: dict) -> dict:
    """Save an API key for ``slug``; return its refreshed provider row (model.options shape + ``authenticated``)."""
    skew = _model_skew_err(rid)
    if skew is not None:
        return skew
    from hermes_cli.auth import PROVIDER_REGISTRY
    from hermes_cli.config import is_managed
    slug, api_key = (params.get("slug") or "").strip(), (params.get("api_key") or "").strip()
    if not slug or not api_key:
        return _err(rid, 4001, "slug and api_key are required")
    if is_managed():
        return _err(rid, 4006, "managed install — credentials are read-only")
    if not (pconfig := PROVIDER_REGISTRY.get(slug)):
        return _err(rid, 4002, f"unknown provider: {slug}")
    if pconfig.auth_type != "api_key":
        return _err(rid, 4003, f"{pconfig.name} uses {pconfig.auth_type} auth — run `hermes model` to configure")
    if not pconfig.api_key_env_vars:
        return _err(rid, 4004, f"no env var defined for {pconfig.name}")
    # Save the key to ~/.hermes/.env via the unified credential lifecycle so any stale config.yaml mirror of
    # the previous key (model.api_key, custom_providers[*].api_key) is rotated in the same action (#62269).
    env_var = pconfig.api_key_env_vars[0]
    from hermes_cli.config import load_env
    from hermes_cli.credential_lifecycle import save_provider_env_credential  # also rotates stale config.yaml mirrors
    previous = load_env().get(env_var)
    # Under the profile scope the save publishes into the addressed profile's secret scope (and the
    # shared os.environ only for the launch profile), so the refreshed inventory below sees it.
    save_provider_env_credential(env_var, api_key)
    if api_key != previous:  # a same-key re-save connects nothing new
        from hermes_cli.observability.shared_metrics_setup import record_provider_setup_done
        record_provider_setup_done(_resolve_session_platform(), slug, background=True)
    # The launch profile's boot record may still say "nothing configured"; the gated picker's own chat
    # waits on setup.status, so the fresh key must move the record (+ setup.ready). reconcile_record
    # leaves it alone when the bound home is another profile's.
    from hermes_cli.free_tier_bootstrap import reconcile_record
    reconcile_record()
    # Shared inventory builder (lock-step with model.options / dashboard); picker_hints carries `authenticated`.
    from hermes_cli.inventory import build_models_payload
    payload = build_models_payload(_model_picker_context(_session_agent(params)), picker_hints=True, max_models=50)
    provider_data = next((p for p in payload["providers"] if p["slug"] == slug), None)
    if provider_data is None:  # key saved but provider didn't appear — still success
        provider_data = {"slug": slug, "name": pconfig.name, "is_current": False, "models": [], "total_models": 0}
    provider_data["authenticated"] = True  # synthetic fallback bypasses picker_hints
    return _ok(rid, {"provider": provider_data})

def _(rid, params: dict) -> dict:
    """Remove all credentials (env keys AND OAuth/pool state) for provider ``slug``."""
    from hermes_cli import managed_scope
    from hermes_cli.auth import PROVIDER_REGISTRY, clear_provider_auth
    from hermes_cli.config import env_write_refusal, load_env
    from hermes_cli.credential_lifecycle import remove_provider_env_credential
    if not (slug := (params.get("slug") or "").strip()):
        return _err(rid, 4001, "slug is required")
    pconfig = PROVIDER_REGISTRY.get(slug)
    # Remove EVERY env var plus its mirrors or the provider resurrects in the picker after restart.
    env_vars = (pconfig.api_key_env_vars if pconfig else None) or ()
    # Ask the .env lock about every var before removing any: a refusal part-way through left the earlier stores
    # stripped. A locked var that holds nothing is no refusal (a package-managed install keeps keys in auth.json).
    removable = []
    for ev in env_vars:
        if (refusal := env_write_refusal(ev, "remove")) is None:
            removable.append(ev)
        elif managed_scope.is_env_managed(ev) or os.environ.get(ev) or load_env().get(ev):
            return _err(rid, 5035, refusal)
    cleared_env = any([remove_provider_env_credential(ev).get("found") for ev in removable])
    cleared_auth = clear_provider_auth(slug)  # full disconnect: OAuth grants go too
    if not cleared_env and not cleared_auth:
        return _err(rid, 4005, f"no credentials found for {slug}")
    return _ok(rid, {"slug": slug, "name": pconfig.name if pconfig else slug, "disconnected": True})

def _(rid, params: dict) -> dict:
    key = params.get("key", "")
    getter = _CONFIG_GETTERS.get(key)
    if getter is None:
        return _err(rid, 4002, f"unknown config key: {key}")
    try:
        return _ok(rid, getter(params))
    except Exception as e:
        if key not in _CONFIG_GET_ERR:
            raise
        return _err(rid, _CONFIG_GET_ERR[key], str(e))

def _(rid, params: dict) -> dict:
    """Readiness probe for the session a client is about to open (setup.status is True if ANY
    provider auth state is discoverable): ok=False + the auth error when the model can't be served,
    so UIs surface onboarding before a doomed prompt. Without ``provider`` it runs the SAME
    resolver as session creation (``_resolve_agent_model_runtime``: startup model + provider pin,
    then the configured fallback chain) — a probe that ignores the chain shows onboarding for a
    backend whose sessions build fine. An explicit ``provider`` stays a strict single-provider
    check so onboarding can verify the provider just connected without another provider's
    fallback masking a failed connection. ``profile`` answers for THAT profile's pin and ``.env``;
    unknown -> ``ok=False``."""
    try:
        from hermes_cli.runtime_provider import resolve_runtime_provider
        from hermes_cli.auth import has_usable_secret
        from hermes_cli.main import _has_any_provider_configured
        requested = str(params.get("provider") or "").strip() or None

        def probe(profile, scoped):
            startup_model, startup_provider = _resolve_startup_runtime()
            if requested:
                model, runtime = startup_model, resolve_runtime_provider(
                    requested=requested, target_model=startup_model or None)
            else:
                model, runtime = _resolve_agent_model_runtime(None, None)
            provider_configured = bool(_has_any_provider_configured(strict_profile_scope=bool(profile)))
            provider = runtime.get("provider") or "provider"
            source = str(runtime.get("source") or "")
            # Without an explicit ``provider`` this probe ran the startup pin and then the
            # configured fallback chain; when the chain only resolves at its tail, ``runtime``
            # stops there and the failure blames a provider the user never pinned (#124939).
            # Attribute failures to the pin (startup pin, else the config model pin).
            cfg_model = _load_cfg().get("model")
            pinned = (requested or startup_provider
                      or (str(cfg_model.get("provider") or "").strip() if isinstance(cfg_model, dict) else ""))
            blamed = pinned or provider

            def fail(error, src):
                return {"ok": False, "provider": blamed, "model": model,
                        "source": src, "error": error, **scoped}
            if (not provider_configured and provider == "bedrock"
                    and source in {"iam-role", "aws-sdk-default-chain"}):
                return fail("No Hermes provider is configured.", source)
            api_key = runtime.get("api_key")
            api_key_text = "" if callable(api_key) else str(api_key or "").strip()
            if not (callable(api_key) or api_key_text in {"aws-sdk", "no-key-required"}
                    or has_usable_secret(api_key_text) or bool(runtime.get("command"))):
                return fail(f"No usable credentials found for {blamed}.", runtime.get("source"))
            from hermes_cli.anon_auth import route_is_welcome_host
            # free_tier_route is keyed on the SELECTED route (the welcome host serves only nous/welcome), not
            # on profile state: a paid Nous key beside a free-tier identity must not read as free.
            return {"ok": True, "provider": runtime.get("provider"), "model": model,
                    "source": runtime.get("source"),
                    "free_tier_route": provider == "nous" and route_is_welcome_host(runtime.get("base_url")),
                    **scoped}
        return _readiness_check(rid, params, probe, probe_key=f"runtime:{requested or ''}",
                                wait_seconds=_READINESS_SHARE_WAIT_SECONDS)
    except Exception as e:
        return _ok(rid, {"ok": False, "error": str(e)})

def _(rid, params: dict) -> dict:
    key, value = params.get("key", ""), params.get("value", "")
    session = _sessions.get(params.get("session_id", ""))
    if session is None and params.get("session_id") and key in _SESSION_SCOPED_KEYS \
            and _word(params.get("scope")) != "global":
        return _sess_nowait(params, rid)[1]
    handler = _CONFIG_SETTERS.get(key)
    if handler is None and key.startswith("details_mode."):
        handler = _set_details_section
    elif handler is None and key in _DISPLAY_TOGGLE_KEYS:
        handler = _set_display_toggle
    if handler is None:
        return _err(rid, 4002, f"unknown config key: {key}")
    return handler(rid, params, key, value, session)

def _(rid, params):
    from tui_gateway.connector_payload import connector_ui_payload

    request, session, error = _operation_params(rid, params)
    if error:
        return error
    operation, error = _operation_for_request(rid, request, session)
    return error or _ok(rid, connector_ui_payload(_operation_view(operation)))

def _(rid, params):
    request, session, error = _operation_params(rid, params)
    if error:
        return error
    operation, error = _operation_for_request(rid, request, session)
    if error:
        return error
    operation.wake.set()
    return _ok(rid, {"status": "ok"})

def _(rid, params):
    from pydantic import ValidationError

    from tui_gateway.connector_refusals import INVALID_ANSWER
    from tui_gateway.contracts.connectors_operation import ConnectionAnswer

    envelope = {key: value for key, value in params.items() if key != "result"}
    request, session, error = _operation_params(rid, envelope)
    if error:
        return error
    try:
        answer = ConnectionAnswer.model_validate(params.get("result"))
    except ValidationError:
        return _connector_rpc_error(rid, *INVALID_ANSWER)
    operation, error = _operation_for_request(rid, request, session)
    if error:
        return error
    if request.owner.type == "account":
        with _account_scope(request):
            return _apply_connection_answer(rid, answer, operation)
    with _session_profile_runtime_scope({"profile_home": session.get("profile_home") or str(_hermes_home)}):
        return _apply_connection_answer(rid, answer, operation)

def _(rid, request):
    from tools.connectors.gateway.errors import GatewayUnavailable
    from tools.connectors.portal.client import PortalConnectorClient
    from tools.connectors.portal.errors import InvalidConnectorSlug
    from tools.connectors.portal.tools_cache import read_tools
    from tui_gateway.contracts.connectors import ConnectorErrorReason, ConnectorToolsResult

    client = PortalConnectorClient()
    client.require_authentication()
    try:
        listing = read_tools(request.slug, client=client, refresh=request.refresh)
    except (InvalidConnectorSlug, GatewayUnavailable):
        return _connector_rpc_error(rid, 4041, ConnectorErrorReason.connector_not_found, "Connector not found.")
    return _ok(rid, ConnectorToolsResult.model_validate(listing, from_attributes=True).model_dump(mode="json"))

def _(rid, request):
    from tools.connectors.gateway.errors import (
        GatewayAuthError,
        GatewayUnavailable,
        IdempotencyConflict,
        ToolGatewayError,
    )
    from tools.connectors.portal.client import PortalConnectorClient
    from tui_gateway.contracts.connectors import ConnectorErrorReason

    try:
        account = PortalConnectorClient().rename_account(request.connection_id, request.alias)
    except IdempotencyConflict:
        return _connector_rpc_error(rid, 4090, ConnectorErrorReason.alias_taken, "That name is already used.")
    except GatewayUnavailable as exc:
        if exc.code == "connection_not_found":
            return _connector_rpc_error(rid, 4041, ConnectorErrorReason.connection_not_found, "Connector account not found.")
        return _connector_rpc_error(rid, 5034, ConnectorErrorReason.accounts_unavailable, "Connector accounts are unavailable.")
    except GatewayAuthError:
        raise
    except ToolGatewayError as exc:
        if exc.code == "org_required":
            raise
        if exc.status == 400:
            return _connector_rpc_error(rid, 4000, ConnectorErrorReason.invalid_params, "That name is invalid.")
        return _connector_rpc_error(rid, 5034, ConnectorErrorReason.accounts_unavailable, "Connector accounts are unavailable.")
    return _ok(rid, _account_row(account).model_dump(mode="json"))

def _(rid, request):
    from tools.connectors.gateway.errors import GatewayAuthError, GatewayUnavailable, ToolGatewayError
    from tools.connectors.portal.client import PortalConnectorClient
    from tui_gateway.contracts.connectors import ConnectorAccountsRemoveResult, ConnectorErrorReason

    try:
        removed = PortalConnectorClient().delete_account(request.connection_id)
    except GatewayUnavailable as exc:
        if exc.code == "connection_not_found":
            return _connector_rpc_error(rid, 4041, ConnectorErrorReason.connection_not_found, "Connector account not found.")
        return _connector_rpc_error(rid, 5034, ConnectorErrorReason.accounts_unavailable, "Connector accounts are unavailable.")
    except GatewayAuthError:
        raise
    except ToolGatewayError as exc:
        if exc.code == "org_required":
            raise
        if exc.code == "invalid_connection_id":
            return _connector_rpc_error(rid, 4000, ConnectorErrorReason.invalid_params, "Connection id is invalid.")
        return _connector_rpc_error(rid, 5034, ConnectorErrorReason.accounts_unavailable, "Connector accounts are unavailable.")
    result = ConnectorAccountsRemoveResult(
        connection_id=removed["connectionId"], connector=removed["connector"], status=removed["status"]
    )
    return _ok(rid, result.model_dump(mode="json"))

def _(rid, _params):
    from tools.connectors.gateway.errors import GatewayAuthError, ToolGatewayError
    from tools.connectors.portal.client import PortalConnectorClient
    from tui_gateway.contracts.connectors import ConnectorErrorReason, ConnectorPolicyGetResult, ConnectorPolicyLayer

    try:
        client = PortalConnectorClient()
        client.require_authentication()
        policy = client.policy()
    except GatewayAuthError as exc:
        return _connector_rpc_error(rid, *_policy_auth_error(exc, ConnectorErrorReason))
    except ToolGatewayError as exc:
        return _connector_rpc_error(rid, *_policy_error(exc, ConnectorErrorReason))
    result = ConnectorPolicyGetResult(
        layers=[
            ConnectorPolicyLayer(kind=layer.kind, revision=layer.revision, body=_contract_policy_body(layer.body))
            for layer in policy.layers
        ],
        effective=_contract_policy_effective(policy.effective),
    )
    return _ok(rid, result.model_dump(mode="json"))

def _(rid, request):
    from tools.connectors.gateway.errors import GatewayAuthError, ToolGatewayError
    from tools.connectors.portal.client import PortalConnectorClient
    from tools.connectors.portal.policy import InvalidMemberPolicy, compose_connector_write, compose_tools_write
    from tui_gateway.contracts.connectors import ConnectorErrorReason, ConnectorPolicySetResult, ToolsChange

    try:
        client = PortalConnectorClient()
        client.require_authentication()
        policy = client.policy()
        member = next((layer.body for layer in policy.layers if layer.kind == "member"), None)
        compose = compose_tools_write if isinstance(request.change, ToolsChange) else compose_connector_write
        body = compose(member, request.change)
        body["expectedRevision"] = request.expected_revision
        result = client.set_policy(body)
    except GatewayAuthError as exc:
        return _connector_rpc_error(rid, *_policy_auth_error(exc, ConnectorErrorReason))
    except InvalidMemberPolicy:
        return _connector_rpc_error(rid, 4000, ConnectorErrorReason.invalid_policy, "Connector policy change is invalid.")
    except ToolGatewayError as exc:
        return _connector_rpc_error(rid, *_policy_error(exc, ConnectorErrorReason))
    return _ok(rid, ConnectorPolicySetResult(
        revision=result.revision, effective=_contract_policy_effective(result.effective)
    ).model_dump(mode="json"))

def _(rid, params: dict) -> dict:
    _install_lease_listener()
    try:
        return _ok(rid, _display_snapshot())
    except Exception as e:
        return _err(rid, _DISPLAY_ERR, str(e))

def _(rid, params: dict) -> dict:
    """One JPEG grab of the bot's screen (``data_url``: null while stopped). Read-only: no lease change.
    Suppressed while a human holds the lease — the frame may show what they are typing — and when
    the lease moved DURING the grab: a takeover racing the framebuffer read means the frame may
    already be the human's session, so it is dropped rather than shipped to every client."""
    try:
        from tools.bot_desktop import lease as _bd_lease
        before = _bd_lease.get()
        if before.holder == _bd_lease.HUMAN:
            return _ok(rid, {"data_url": None, "suppressed": "human_has_control"})
        from tools.bot_desktop.thumbnail import thumbnail_data_url
        data_url = thumbnail_data_url()
        if _bd_lease.get().epoch != before.epoch:
            return _ok(rid, {"data_url": None, "suppressed": "human_has_control"})
        return _ok(rid, {"data_url": data_url})
    except Exception as e:
        return _err(rid, _DISPLAY_ERR, str(e))

def _(rid, params: dict) -> dict:
    _install_lease_listener()
    from tools.bot_desktop import runtime as _bd_runtime
    try:
        _bd_runtime.start()
        return _ok(rid, _display_snapshot())
    except Exception as e:
        return _err(rid, _DISPLAY_ERR, str(e))

def _(rid, params: dict) -> dict:
    """Stopping kills the screen under whoever is on it, so it obeys the same rule as a bare
    display.lease.release: refused while a human holds unless the caller says ``force``."""
    from tools.bot_desktop import lease as _bd_lease, runtime as _bd_runtime
    force = bool(params.get("force"))
    # Refusal and release are ONE lease transition: a takeover landing between a separate human_holds()
    # check and the release would be acknowledged to the human and then silently revoked here.
    if _bd_lease.release(unless_human=not force).holder == _bd_lease.HUMAN:
        return _err(rid, _DISPLAY_ERR, "a human holds this screen; pass force: true to stop it anyway",
                    data={"code": "viewer_mismatch"})
    try:
        stopped = _bd_runtime.stop()
        return _ok(rid, {**_display_snapshot(), "stopped": stopped})
    except Exception as e:
        return _err(rid, _DISPLAY_ERR, str(e))

def _(rid, params: dict) -> dict:
    """Mint a single-use, 30 s ticket for ``/api/display/ws``. The ticket carries the profile home so
    the bridge dials THIS profile's RFB socket, and a server-minted viewer id (returned to the caller,
    who passes it to ``display.lease.acquire`` / ``release``) so the lease can name the holder."""
    from hermes_constants import get_hermes_home
    from hermes_cli.dashboard_auth.ws_tickets import mint_ticket
    from tools.bot_desktop import runtime as _bd_runtime
    try:
        # The bridge dials either the host RFB socket or the sandbox relay; neither exists before start.
        if _bd_runtime.rfb_socket_path() is None and not _bd_runtime.sandbox_screen_running():
            return _err(rid, _DISPLAY_ERR, "this profile's Bot Desktop is not running; call display.start first")
        viewer_id = _mint_viewer_id(str(params.get("viewer_id") or "").strip())
        ticket = mint_ticket(user_id=f"display:{viewer_id}", provider="bot-desktop",
                             extra={"hermes_home": str(get_hermes_home()), "viewer_id": viewer_id})
        return _ok(rid, {"ticket": ticket, "path": "/api/display/ws", "viewer_id": viewer_id,
                         **_display_snapshot()})
    except Exception as e:
        return _err(rid, _DISPLAY_ERR, str(e))

def _(rid, params: dict) -> dict:
    """The Screen pane's answer to the pending default-image switch: ``approve`` true pins the new
    image (the container is recreated on the next terminal call), false pins the current one. Both
    end the offer. Refused when nothing is pending, so a stale pane cannot rewrite the config."""
    from hermes_cli.sandbox_image_switch import decide, pending
    sw = pending()
    if sw is None:
        return _err(rid, _DISPLAY_ERR, "no sandbox image switch is pending for this profile")
    image = decide(sw, approve=bool(params.get("approve", True)))
    return _ok(rid, {"docker_image": image, **_display_snapshot()})

def _(rid, params: dict) -> dict:
    """Start the package install in the background; the renderer follows ``display.install.log`` /
    ``display.install.done``. Refused while one is already running for this profile."""
    from hermes_constants import hermes_home_key
    from tools.bot_desktop import install as _bd_install, runtime as _bd_runtime
    if not _bd_runtime.is_supported_host():
        return _err(rid, _DISPLAY_ERR, "Bot Desktop runs on Linux gateway hosts only")
    if _bd_runtime.in_sandbox():
        return _err(rid, _DISPLAY_ERR, "this profile's screen lives inside the terminal backend's sandbox; give that "
                                       "sandbox an image with the desktop stack (nousresearch/hermes-sandbox:desktop) "
                                       "instead of installing on the gateway host")
    if _bd_runtime.install_command() is None:
        return _err(rid, _DISPLAY_ERR, "no supported package manager (apt-get, dnf, pacman) on this host")
    profile_key = hermes_home_key()

    def _ask_password() -> str:
        # App-level card, no session: it reaches the connection that clicked Install through the
        # transport copy_context() carries below. A client-supplied session_id could route the
        # masked password card into another window's chat, so none is accepted.
        return _ask("display.install.sudo", "", {"profile_key": profile_key}, timeout=300)

    def _line(text: str) -> None:
        _broadcast_global_event("display.install.log", {"profile_key": profile_key, "line": text})

    # The worker thread inherits NO context: the caller's transport (so the sudo card reaches the
    # CLIENT that clicked Install) and the profile scope `_profile_scoped` installed (so status, lock
    # and events all speak for the requested profile) are carried across with copy_context().
    import contextvars
    ctx = contextvars.copy_context()

    def _run() -> None:
        try:
            code = _bd_install.install_packages(ask_password=_ask_password, on_line=_line, claimed=True)
        except Exception as e:
            _line(f"install failed: {e}")
            code = 1
        _broadcast_global_event("display.install.done", {"profile_key": profile_key, "code": code,
                                                         "status": _display_snapshot()})

    try:
        _bd_install.claim()  # atomic: two fast clicks cannot both start a package manager
    except _bd_install.InstallBusy as e:
        return _err(rid, _DISPLAY_ERR, str(e))
    threading.Thread(target=ctx.run, args=(_run,), name=f"bot-desktop-install:{profile_key}", daemon=True).start()
    return _ok(rid, {"started": True, "command": _bd_runtime.install_command(), "profile_key": profile_key})

def _(rid, params: dict) -> dict:
    from tools.bot_desktop import lease as _bd_lease
    viewer_id = str(params.get("viewer_id") or "").strip()
    if not viewer_id:
        return _err(rid, _DISPLAY_ERR, "viewer_id required")
    if (refused := _foreign_viewer_id(rid, viewer_id)) is not None:
        return refused
    lease = _bd_lease.acquire(viewer_id, reason=str(params.get("reason") or ""))
    return _ok(rid, {"lease": _bd_lease.public_view(lease)})

def _(rid, params: dict) -> dict:
    from tools.bot_desktop import lease as _bd_lease
    viewer_id = str(params.get("viewer_id") or "").strip() or None
    # lease.release(None) skips the holder check; a client that lost its viewer id must not be able to
    # yank control from whoever holds it unless it says so explicitly (force).
    if viewer_id is not None and not params.get("force") and (refused := _foreign_viewer_id(rid, viewer_id)) is not None:
        return refused
    # Same atomicity as display.stop: the "is a human holding?" decision happens inside the transition.
    lease = _bd_lease.release(viewer_id, unless_human=viewer_id is None and not params.get("force"))
    if viewer_id is None and lease.holder == _bd_lease.HUMAN:
        return _err(rid, _DISPLAY_ERR, "viewer_id required to release another viewer's lease (or pass force: true)",
                    data={"code": "viewer_mismatch"})
    return _ok(rid, {"lease": _bd_lease.public_view(lease)})

def _(rid, params: dict) -> dict:
    """``{has_guest, enabled, available, notice_pending, model, label}`` for the focused profile.
    ``available``: a guest that carries inference here (the welcome trial, on the desktop's local
    backend). ``enabled``: available, or the trial can still be claimed on this machine. Whether
    inference actually runs on it is a ROUTE question answered by ``setup.runtime_check.free_tier``.
    ``notice_pending`` is true until ``free_tier.ack_notice`` ran for this identity.
    ``nudge_due_in``: seconds until the sign-in offer after a finished task is due (install-wide,
    ``hermes_cli.free_tier_offer``); absent when none is pending. ``connector_nudge_due_in``: the
    same for a guest without the trial that has connected an app.

    A pure read: an identity is never created as a side effect of polling this (NS-845 Q1.2)."""
    try:
        from hermes_cli import anon_auth
        has_guest = anon_auth.has_guest()
        available = anon_auth.free_inference_active()
        enabled = available or _trial_claimable()
        payload = {
            "has_guest": has_guest, "enabled": enabled, "available": available,
            "notice_pending": bool(available and anon_auth.guest_notice_pending()),
            "model": anon_auth.GUEST_MODEL, "label": anon_auth.FREE_TIER_LABEL}
        from hermes_cli import free_tier_offer
        for key, kind in (("nudge_due_in", free_tier_offer.TRIAL), ("connector_nudge_due_in", free_tier_offer.CONNECTOR)):
            if (due_in := free_tier_offer.offer_due_in(kind)) is not None:
                payload[key] = due_in
        if enabled and not has_guest:
            # Why there is no identity, when the last claim failed:
            # ``{error, error_code, retryable, retry_after}`` (the mint memo's verdict).
            payload.update(anon_auth.last_mint_failure() or {})
        # A browser challenge the account service is waiting on (``anon_challenge``): the same
        # payload the ``free_tier.challenge`` event carried, for a client that connected after it.
        from hermes_cli import anon_challenge
        challenge = anon_challenge.pending_challenge()
        if challenge:
            payload["challenge"] = challenge
        return _ok(rid, payload)
    except Exception as e:
        return _err(rid, 5090, str(e))

def _(rid, params: dict) -> dict:
    """The user's retry of a welcome-trial claim that failed: claims it when nothing blocks it here
    (blocking, short timeout; the one attempt allowed inside the mint memo's cooldown). ``{has_guest,
    enabled}``, plus ``{error, error_code, retryable, retry_after}`` when the portal refused."""
    try:
        from hermes_cli import anon_auth, free_tier_bootstrap, welcome_trial
        from hermes_cli.auth_constants import AuthError
        if _trial_claimable():
            try:
                welcome_trial.claim_desktop_free_tier(force=True)
            except AuthError as exc:   # memoised by the mint primitive before it re-raised
                logger.info("welcome trial claim failed: %s", exc)
            if not params.get("profile"):
                # The launch profile: ``setup.status`` and the ``setup.ready`` listeners move with it.
                free_tier_bootstrap.refresh_record()
        has_guest = anon_auth.has_guest()
        enabled = anon_auth.free_inference_active() or _trial_claimable()
        payload = {"has_guest": has_guest, "enabled": enabled}
        if enabled and not has_guest:
            payload.update(anon_auth.last_mint_failure() or {})
        return _ok(rid, payload)
    except Exception as e:
        return _err(rid, 5092, str(e))

